 const doLogin=async(e:FormEvent)=>{e.preventDefault();setError('');try{const r=await api<{user:User;attendance?:{checkedIn?:boolean;noSchedule?:boolean;alreadyCheckedIn?:boolean;shift?:string}}>('/auth/login',{method:'POST',body:JSON.stringify(login)});setUser(r.user);if(r.user.mustChangePassword)setShowPw(true);if(r.attendance?.noSchedule)setNotice('Hôm nay bạn không có lịch làm việc nên không được điểm danh.');else if(r.attendance?.checkedIn)setNotice('Đã điểm danh thành công; ca làm hôm nay đã được ghi nhận vào bảng lương.');else if(r.attendance?.alreadyCheckedIn)setNotice('Bạn đã được điểm danh hôm nay.');}catch(e){setError((e as Error).message);}};
 const requestOtp=async(e:FormEvent)=>{e.preventDefault();setForgotError('');try{const r=await api<{message:string}>('/auth/forgot-password',{method:'POST',body:JSON.stringify({username:forgot.username,email:forgot.email})});setForgotStep(2);setForgotMessage(r.message)}catch(e){setForgotError((e as Error).message)}};
 const resetForgottenPassword=async(e:FormEvent)=>{e.preventDefault();setForgotError('');try{await api('/auth/reset-password',{method:'POST',body:JSON.stringify(forgot)});setShowForgot(false);setForgotStep(1);setLogin({...login,username:forgot.username,password:''});setError('');setForgotMessage('');setForgotError('');setLoginMessage('Đã đặt lại mật khẩu. Hãy đăng nhập bằng mật khẩu mới.')}catch(e){setForgotError((e as Error).message)}};
