 const exportCsv=async()=>{try{const r=await fetch(`${API}/reports/orders.csv`,{credentials:'include'});if(!r.ok)throw new Error('Không thể xuất báo cáo.');const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`OrderHub-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}catch(e){setError((e as Error).message);}};
 const importReconciliation=async(file:File)=>{setError('');try{const wb=XLSX.read(await file.arrayBuffer(),{cellDates:true});const firstSheet=wb.SheetNames[0];if(!firstSheet||!wb.Sheets[firstSheet])throw new Error('Tệp Excel không có trang tính để đọc.');const rows=XLSX.utils.sheet_to_json<unknown[]>(wb.Sheets[firstSheet],{header:1,raw:true,defval:''});if(rows.length<2)throw new Error('Tệp chưa có dòng dữ liệu.');const normalize=(value:unknown)=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[đ]/g,'d').trim();const headerRow=rows.findIndex(row=>{const values=(Array.isArray(row)?row:[]).map(normalize);return values.some(v=>v.includes('ma van don')||v.includes('tracking code')||v.includes('tracking number'))&&values.some(v=>v.includes('trang thai')||v.includes('status'))});if(headerRow<0)throw new Error('Không tìm thấy dòng tiêu đề có cả “Mã vận đơn” và “Trạng thái”. Hãy dùng file Excel xuất danh sách vận đơn.');const headers=(rows[headerRow]||[]).map(normalize);const codeCol=headers.findIndex(v=>v.includes('ma van don')||v.includes('tracking code')||v.includes('tracking number'));const statusCol=headers.findIndex(v=>v==='trang thai'||v==='trang thai don hang'||v==='trang thai giao hang'||v==='status'||v==='order status'||v==='shipment status');if(codeCol<0||statusCol<0)throw new Error('Không xác định được đúng cột mã vận đơn hoặc trạng thái đơn hàng.');const parsed:{trackingCode:string;status:'pending'|'delivered'|'returned'}[]=[];for(const row of rows.slice(headerRow+1)){if(!Array.isArray(row))continue;const code=String(row[codeCol]??'').trim();const raw=normalize(row[statusCol]);if(!code||!raw)continue;let status:'pending'|'delivered'|'returned'|null=null;if(/giao thanh cong/.test(raw))status='delivered';else if(/dang chuyen hoan|da duyet hoan|^da tra(?:\s|$)|hoan tra|tra hang|returned/.test(raw))status='returned';if(status)parsed.push({trackingCode:code,status})}if(!parsed.length)throw new Error('Không có trạng thái cần cập nhật. Chỉ nhận “Giao thành công” để đánh dấu đã giao và “Đang chuyển hoàn”, “Đã duyệt hoàn” hoặc “Đã trả” để đánh dấu hoàn trả.');setBulkRows(parsed);setShowBulk(true)}catch(e){setError((e as Error).message||'Không đọc được tệp Excel. Hãy kiểm tra tệp .xlsx hoặc .xls rồi thử lại.')}};
 const confirmReconciliation=async()=>{try{const r=await api<{updated:number;missing:string[]}>('/orders/bulk-status',{method:'POST',body:JSON.stringify({rows:bulkRows})});await refresh();setShowBulk(false);setNotice(`Đã cập nhật trạng thái ${r.updated} đơn.${r.missing.length?` Không tìm thấy: ${r.missing.slice(0,8).join(', ')}${r.missing.length>8?'…':''}`:''}`)}catch(e){setError((e as Error).message)}};
